using System;using System.IO;using System.Text;namespace Mapping{    /// <summary>    /// SMIC IGBT Project Mapping    /// </summary>    public class SMECConverter : MapConverterSkeleton    {
        static SMECConverter()        {            MapConverterMap.LookupWithDefault("SMEC", new SMECConverter());
        }        private BinCode[,,,] OriginalBinCodes { get; set; }        /// <summary>        ///         /// </summary>        public SMECConverter()        {        }        /// <summary>        ///         /// </summary>        /// <param name="mapFile"></param>        /// <returns></returns>        public override MapData Read(string mapFile, bool isOriginalMap = false)        {            if (string.IsNullOrWhiteSpace(mapFile))            {                throw new ArgumentNullException(nameof(mapFile));            }            using (FileStream fs = new FileStream(mapFile, FileMode.Open, FileAccess.Read))            {                using (StreamReader sr = new StreamReader(fs, Encoding.Default))                {                    var md = this.ReadSMEC(sr, isOriginalMap);                    md.SubstrateID = Path.GetFileNameWithoutExtension(mapFile);                    return md;                }            }        }        /// <summary>        ///         /// </summary>        /// <param name="map"></param>        /// <param name="fileName"></param>        public override void Save(Map map, string fileName)        {            if (string.IsNullOrWhiteSpace(fileName))            {                throw new ArgumentNullException(nameof(fileName));            }            int sum = map.Count();            int goodCount = map.Count(UnitState.Good);            int pickedCount = map.CountPicked();            using (FileStream fs = new FileStream(Path.GetFullPath(fileName), FileMode.OpenOrCreate, FileAccess.ReadWrite))            {                using (StreamWriter sw = new StreamWriter(fs, Encoding.Default))                {                    sw.WriteLine("Format Version:1.1");                    sw.WriteLine("Device Name:");                    sw.WriteLine($"Lot Number:");                    sw.WriteLine($"Vendor Lot Id:");                    sw.WriteLine($"Wafer Number:");                    sw.WriteLine("Origin Loc:Bottom Left");                    sw.WriteLine("Wafer Flat:Down");                    sw.WriteLine($"Column Count:{map.Columns}");                    sw.WriteLine($"Row Count:{map.Rows}");                    sw.WriteLine("Null Bin:.");                    sw.WriteLine($"Gross Die:{sum}");                    sw.WriteLine($"Pass Die:{goodCount}");                    foreach (var bin in map.Bins)                    {                        var state = bin.Work ? "PASS" : "FAIL";                        int count = map.Count(bin);                        sw.WriteLine($"BinInformation:{bin.FormattedCode}, {count}, {state}");                    }                    for (int i = 0; i < map.Rows; i++)                    {                        StringBuilder builder = new StringBuilder();                        for (int j = 0; j < map.Columns; j++)                        {                            var unit = OriginalBinCodes[0, 0, i, j];                            builder.Append(unit.FormattedCode);                        }                        sw.WriteLine(builder.ToString());                    }                    sw.WriteLine("[WorkingMap]");                    for (int i = 0; i < map.Rows; i++)                    {                        StringBuilder builder = new StringBuilder();                        for (int j = 0; j < map.Columns; j++)                        {                            string binCode = ".";                            var unit = map[i, j];                            if (unit.Bin == map.NullBin)                            {                                binCode = ".";                            }                            else if (unit.State == UnitState.Picked || unit.State == UnitState.Processed)                            {                                binCode = "@";                            }                            else if (unit.State == UnitState.Reject)                            {                                binCode = "&";                            }                            else                            {                                binCode = unit.Bin.FormattedCode;                            }                            builder.Append(binCode);                        }                        sw.WriteLine(builder.ToString());                    }                }            }        }        private MapData ReadSMEC(StreamReader sr, bool isOriginalMap)        {            var mapData = new MapData();            // Format Version            var line = sr.ReadLine();            var version = line.Split(':')[1];            // Device Name            sr.ReadLine();            // Lot Number            line = sr.ReadLine();            //mapData.LotID = line.Split(':')[1].Trim();            // Vendor Lot Id            sr.ReadLine();            if (version == "1.2")            {                // lot id-wafer ID                sr.ReadLine();            }            // Wafer Number            line = sr.ReadLine();            //mapData.SlotNo = Convert.ToInt32(line.Split(':')[1].Trim());            // Origin Loc            line = sr.ReadLine();            //mapData.OriginLocation = OriginLocation.LowerLeft;            // Wafer Flat            sr.ReadLine();            // Column Count            line = sr.ReadLine();            mapData.Columns = Convert.ToInt32(line.Split(':')[1].Trim());            // Row Count            line = sr.ReadLine();            mapData.Rows = Convert.ToInt32(line.Split(':')[1].Trim());            // Null Bin            line = sr.ReadLine();            mapData.NullBin = Bin.CreateNullBin(line.Split(':')[1].Trim()[0]);            // Gross Die            sr.ReadLine();            // Pass Die            sr.ReadLine();            // BinInformation            mapData.Bins = new BinCollection();            do            {                line = sr.ReadLine();                if (!line.Contains("BinInformation"))                {                    break;                }                var temps = line.Split(':')[1].Split(',');                char binCode = temps[0].Trim()[0];                bool work = temps[2].Trim().ToUpper().Contains("PASS");                Bin bin = new Bin(new BinCode(binCode), work);                mapData.Bins.Add(bin);            } while (true);            // BinCode            int rowCount = 0;            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            var chars = line.Trim().ToCharArray();            for (int c = 0; c < mapData.Columns; c++)            {                mapData.BinCodes[0, 0, rowCount, c] = chars[c];            }            rowCount++;            do            {                line = sr.ReadLine();                if (line == "[WorkingMap]" && !isOriginalMap)                {                    //r = 0;                    mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];                    rowCount = 0;                    continue;                }                if (line is null || (line == "[WorkingMap]" && isOriginalMap))                {                    break;                }                if (string.IsNullOrWhiteSpace(line))                {                    continue;                }                chars = line.Trim().ToCharArray();                for (int c = 0; c < mapData.Columns; c++)                {                    BinCode code = new BinCode(chars[c]);                    if (code.Code == '@') // picked bin                    {                    }                    else if (code.Code == '&') // reject bin                    {                    }                    mapData.BinCodes[0, 0, rowCount, c] = code;                }                rowCount++;            } while (true);            if (isOriginalMap)                OriginalBinCodes = mapData.BinCodes;            return mapData;        }    }}